insert into public.recipes (id, name, description, meal_type, main, emoji, prep_time_min, difficulty, calories, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg, ingredients, seasonings, instructions, appliances, keywords, dietary_tags, i18n, sort) values
  ('l-bean-corn-avocado-salad', 'Bean, Corn and Avocado Salad', 'No-cook salad of kidney beans, corn, peppers, tomato and avocado', 'lunch', 'kidney beans', '🥑', 10, 'quick', 547, 18, 64, 29, 22, 16, 529, '[{"name":"kidney beans","amount":150,"unit":"g"},{"name":"corn","amount":80,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp ground cumin","squeeze of lime juice","salt","handful of fresh coriander"]'::jsonb, '["Drain and rinse the kidney beans and corn","Dice the peppers, tomato and avocado","Toss everything with the olive oil, cumin, lime juice, salt and coriander"]'::jsonb, '[]'::jsonb, '["mexican","fresh","quick","light","kidney beans","corn","peppers","tomato","avocado","olive oil","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Салата с боб, царевица и авокадо","description":"Салата без готвене от червен боб, царевица, чушки, домат и авокадо","instructions":["Отцедете и изплакнете червения боб и царевицата","Нарежете чушките, домата и авокадото на кубчета","Разбъркайте всичко със зехтина, кимиона, сока от лайм, сол и кориандъра"],"seasonings":["1/2 ч.л. смлян кимион","няколко капки сок от лайм","сол","шепа пресен кориандър"]},"nl":{"name":"Salade met bonen, mais en avocado","description":"Salade zonder koken van kidneybonen, mais, paprika, tomaat en avocado","instructions":["Laat de kidneybonen en de mais uitlekken en spoel ze af","Snijd de paprika, de tomaat en de avocado in blokjes","Meng alles met de olijfolie, de komijn, het limoensap, zout en de koriander"],"seasonings":["1/2 tl gemalen komijn","kneepje limoensap","zout","handje verse koriander"]}}'::jsonb, 180),
  ('l-caprese-pasta-salad', 'Caprese Pasta Salad', 'Cold pasta with mozzarella, tomato, spinach and pesto', 'lunch', 'mozzarella', '🍅', 15, 'quick', 577, 26, 66, 23, 5, 6, 527, '[{"name":"pasta","amount":75,"unit":"g"},{"name":"mozzarella","amount":60,"unit":"g"},{"name":"tomato","amount":150,"unit":"g"},{"name":"pesto","amount":20,"unit":"g"},{"name":"spinach","amount":30,"unit":"g"}]'::jsonb, '["black pepper","pinch of salt"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet, drain and rinse under cold water","Dice the tomato and tear the mozzarella into pieces","Toss the pasta with the pesto, tomato, mozzarella and spinach and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","fresh","quick","pasta","mozzarella","tomato","pesto","spinach","stovetop","lunch"]'::jsonb, '["vegetarian","halal","kosher"]'::jsonb, '{"bg":{"name":"Салата с паста „Капрезе“","description":"Студена паста с моцарела, домат, спанак и песто","instructions":["Сварете пастата в подсолена вряща вода според указанията на опаковката, отцедете я и я изплакнете със студена вода","Нарежете домата на кубчета и накъсайте моцарелата на парчета","Разбъркайте пастата с пестото, домата, моцарелата и спанака и овкусете с пипер"],"seasonings":["черен пипер","щипка сол"]},"nl":{"name":"Pastasalade caprese","description":"Koude pasta met mozzarella, tomaat, spinazie en pesto","instructions":["Kook de pasta in kokend water met zout volgens de verpakking, giet af en spoel onder koud water","Snijd de tomaat in blokjes en scheur de mozzarella in stukjes","Meng de pasta met de pesto, de tomaat, de mozzarella en de spinazie en breng op smaak met peper"],"seasonings":["zwarte peper","snufje zout"]}}'::jsonb, 181),
  ('l-tuna-pasta-salad', 'Tuna Pasta Salad', 'Pasta salad with tuna, corn, tomato and cucumber in a lemon olive oil dressing', 'lunch', 'tuna', '🐟', 15, 'quick', 495, 31, 66, 13, 5, 8, 360, '[{"name":"tuna","amount":100,"unit":"g"},{"name":"pasta","amount":70,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["squeeze of lemon juice","salt","black pepper","pinch of dried oregano"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet, drain and rinse under cold water","Dice the tomato and cucumber","Toss the pasta with the drained tuna, corn, tomato, cucumber, olive oil, lemon juice and oregano and season"]'::jsonb, '["stovetop"]'::jsonb, '["italian","fresh","quick","light","tuna","pasta","corn","tomato","cucumber","olive oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Салата с паста и риба тон","description":"Салата с паста, риба тон, царевица, домат и краставица с дресинг от лимон и зехтин","instructions":["Сварете пастата в подсолена вряща вода според указанията на опаковката, отцедете я и я изплакнете със студена вода","Нарежете домата и краставицата на кубчета","Разбъркайте пастата с отцедената риба тон, царевицата, домата, краставицата, зехтина, лимоновия сок и ригана и овкусете"],"seasonings":["няколко капки лимонов сок","сол","черен пипер","щипка сух риган"]},"nl":{"name":"Pastasalade met tonijn","description":"Pastasalade met tonijn, mais, tomaat en komkommer in een dressing van citroen en olijfolie","instructions":["Kook de pasta in kokend water met zout volgens de verpakking, giet af en spoel onder koud water","Snijd de tomaat en de komkommer in blokjes","Meng de pasta met de uitgelekte tonijn, de mais, de tomaat, de komkommer, de olijfolie, het citroensap en de oregano en breng op smaak"],"seasonings":["kneepje citroensap","zout","zwarte peper","snufje gedroogde oregano"]}}'::jsonb, 182),
  ('l-minestrone', 'Minestrone', 'Chunky vegetable and bean soup with pasta and parmesan', 'lunch', 'kidney beans', '🥣', 30, 'balanced', 444, 19, 66, 13, 13, 16, 584, '[{"name":"kidney beans","amount":80,"unit":"g"},{"name":"pasta","amount":40,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"zucchini","amount":80,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"parmesan","amount":10,"unit":"g"}]'::jsonb, '["1 stock cube","{400} ml water","1 tsp dried oregano","black pepper"]'::jsonb, '["Dice the onion, carrots and zucchini and soften them in the olive oil in a pot for 5 minutes","Add the chopped tomatoes, water, stock cube and oregano and simmer for 10 minutes","Add the pasta and drained kidney beans and cook for 8 to 10 minutes until the pasta is tender","Serve topped with the grated parmesan and black pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","light","kidney beans","pasta","carrots","zucchini","chopped tomatoes","onion","olive oil","parmesan","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Минестроне","description":"Гъста супа от зеленчуци и боб с паста и пармезан","instructions":["Нарежете лука, морковите и тиквичката на кубчета и ги задушете в зехтина в тенджера за 5 минути","Добавете нарязаните домати, водата, кубчето бульон и ригана и варете на тих огън 10 минути","Добавете пастата и отцедения червен боб и варете 8–10 минути, докато пастата омекне","Поднесете с настъргания пармезан и черен пипер отгоре"],"seasonings":["1 кубче бульон","{400} мл вода","1 ч.л. сух риган","черен пипер"]},"nl":{"name":"Minestrone","description":"Stevige soep van groenten en bonen met pasta en Parmezaanse kaas","instructions":["Snijd de ui, de wortels en de courgette in blokjes en bak ze 5 minuten zacht in de olijfolie in een pan","Voeg de tomatenblokjes, het water, het bouillonblokje en de oregano toe en laat 10 minuten zachtjes koken","Voeg de pasta en de uitgelekte kidneybonen toe en kook 8 tot 10 minuten tot de pasta gaar is","Serveer met de geraspte Parmezaanse kaas en zwarte peper erop"],"seasonings":["1 bouillonblokje","{400} ml water","1 tl gedroogde oregano","zwarte peper"]}}'::jsonb, 183),
  ('l-chicken-pesto-pasta', 'Chicken Pesto Pasta', 'Pasta with pan-fried chicken, pesto, spinach and tomato', 'lunch', 'chicken', '🍝', 20, 'quick', 536, 40, 59, 15, 5, 5, 351, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"pasta","amount":70,"unit":"g"},{"name":"pesto","amount":25,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain, keeping a little of the water","Cut the chicken into strips, season and fry in a non-stick pan over medium-high heat for 6 minutes until golden","Add the diced tomato and spinach and cook for 1 minute until the spinach wilts","Toss in the pasta, pesto and a splash of the pasta water"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","light","chicken","pasta","pesto","spinach","tomato","stovetop","lunch"]'::jsonb, '["halal"]'::jsonb, '{"bg":{"name":"Паста с пилешко и песто","description":"Паста със запържено пилешко, песто, спанак и домат","instructions":["Сварете пастата в подсолена вряща вода според указанията на опаковката и я отцедете, като запазите малко от водата","Нарежете пилешкото на ивици, овкусете го и го запържете в незалепващ тиган на умерено силен огън за 6 минути до златисто","Добавете нарязания на кубчета домат и спанака и гответе 1 минута, докато спанакът омекне","Добавете пастата, пестото и малко от водата от пастата и разбъркайте"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Pasta met kip en pesto","description":"Pasta met gebakken kip, pesto, spinazie en tomaat","instructions":["Kook de pasta in kokend water met zout volgens de verpakking en giet af; bewaar een beetje kookvocht","Snijd de kip in reepjes, kruid ze en bak ze 6 minuten in een koekenpan met antiaanbaklaag op middelhoog tot hoog vuur goudbruin","Voeg de tomatenblokjes en de spinazie toe en bak 1 minuut tot de spinazie slinkt","Schep de pasta, de pesto en een scheutje kookvocht erdoor"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 184),
  ('l-spinach-mushroom-frittata', 'Spinach and Mushroom Frittata', 'Thick Italian omelette with mushrooms, spinach and parmesan, with bread', 'lunch', 'eggs', '🍳', 20, 'quick', 497, 35, 24, 29, 5, 5, 623, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"spinach","amount":60,"unit":"g"},{"name":"mushrooms","amount":80,"unit":"g"},{"name":"parmesan","amount":15,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Slice the mushrooms and onion and fry them in the olive oil in a small non-stick pan for 5 minutes","Add the spinach and let it wilt","Beat the eggs with the grated parmesan, salt and pepper, pour over the vegetables and cook over low heat, covered, for 6 to 8 minutes until set","Slide onto a plate and serve with the bread"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","light","eggs","spinach","mushrooms","parmesan","onion","olive oil","bread","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Фритата със спанак и гъби","description":"Дебел италиански омлет с гъби, спанак и пармезан, с хляб","instructions":["Нарежете гъбите и лука на филийки и ги запържете в зехтина в малък незалепващ тиган за 5 минути","Добавете спанака и го оставете да омекне","Разбийте яйцата с настъргания пармезан, сол и пипер, залейте зеленчуците и гответе на слаб огън под капак 6–8 минути, докато стегне","Плъзнете в чиния и поднесете с хляба"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Frittata met spinazie en champignons","description":"Dikke Italiaanse omelet met champignons, spinazie en Parmezaanse kaas, met brood","instructions":["Snijd de champignons en de ui in plakjes en bak ze 5 minuten in de olijfolie in een kleine koekenpan met antiaanbaklaag","Voeg de spinazie toe en laat hem slinken","Klop de eieren los met de geraspte Parmezaanse kaas, zout en peper, giet ze over de groenten en bak 6 tot 8 minuten op laag vuur met het deksel op de pan tot het ei gestold is","Laat op een bord glijden en serveer met het brood"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 185),
  ('l-pasta-e-ceci', 'Pasta e Ceci', 'Thick Italian chickpea and pasta soup with tomato and garlic', 'lunch', 'chickpeas', '🥣', 25, 'balanced', 509, 17, 80, 15, 14, 14, 501, '[{"name":"chickpeas","amount":120,"unit":"g"},{"name":"pasta","amount":50,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"carrots","amount":40,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 stock cube","{350} ml water","1 tsp dried rosemary","black pepper"]'::jsonb, '["Finely dice the onion and carrots and soften them in the olive oil for 5 minutes, then add the chopped garlic and rosemary","Add the chopped tomatoes, water, stock cube and drained chickpeas and simmer for 8 minutes","Crush some of the chickpeas against the side of the pot to thicken the soup","Add the pasta and cook for 8 to 10 minutes, stirring, until tender, then season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","light","chickpeas","pasta","chopped tomatoes","onion","carrots","garlic","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Паста е чечи","description":"Гъста италианска супа от нахут и паста с домати и чесън","instructions":["Нарежете лука и морковите на ситни кубчета и ги задушете в зехтина за 5 минути, след което добавете накълцания чесън и розмарина","Добавете нарязаните домати, водата, кубчето бульон и отцедения нахут и варете на тих огън 8 минути","Намачкайте част от нахута в стената на тенджерата, за да се сгъсти супата","Добавете пастата и варете 8–10 минути, като бъркате, докато омекне, след което овкусете с пипер"],"seasonings":["1 кубче бульон","{350} мл вода","1 ч.л. сух розмарин","черен пипер"]},"nl":{"name":"Pasta e ceci","description":"Dikke Italiaanse soep van kikkererwten en pasta met tomaat en knoflook","instructions":["Snijd de ui en de wortels in kleine blokjes en bak ze 5 minuten zacht in de olijfolie; voeg dan de gehakte knoflook en de rozemarijn toe","Voeg de tomatenblokjes, het water, het bouillonblokje en de uitgelekte kikkererwten toe en laat 8 minuten zachtjes koken","Plet een deel van de kikkererwten tegen de wand van de pan om de soep te binden","Voeg de pasta toe en kook 8 tot 10 minuten al roerend gaar; breng dan op smaak met peper"],"seasonings":["1 bouillonblokje","{350} ml water","1 tl gedroogde rozemarijn","zwarte peper"]}}'::jsonb, 186),
  ('l-turkey-bolognese', 'Quick Turkey Bolognese', 'Lean turkey mince in a tomato sauce with pasta', 'lunch', 'turkey mince', '🍝', 25, 'balanced', 544, 35, 66, 16, 7, 9, 276, '[{"name":"turkey mince","amount":120,"unit":"g"},{"name":"pasta","amount":70,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"carrots","amount":40,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Finely dice the onion and carrots and soften them in the olive oil for 4 minutes","Add the turkey mince and brown it for 5 minutes, then stir in the chopped garlic and oregano","Add the chopped tomatoes and simmer for 10 minutes","Meanwhile cook the pasta in salted boiling water, drain and toss with the sauce"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","light","turkey mince","pasta","chopped tomatoes","onion","carrots","garlic","olive oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Бързо болонезе с пуешка кайма","description":"Постна пуешка кайма в доматен сос с паста","instructions":["Нарежете лука и морковите на ситни кубчета и ги задушете в зехтина за 4 минути","Добавете пуешката кайма и я запържете 5 минути, след което добавете накълцания чесън и ригана","Добавете нарязаните домати и варете на тих огън 10 минути","Междувременно сварете пастата в подсолена вряща вода, отцедете я и я разбъркайте със соса"],"seasonings":["1 ч.л. сух риган","сол","черен пипер"]},"nl":{"name":"Snelle bolognese met kalkoen","description":"Mager kalkoengehakt in tomatensaus met pasta","instructions":["Snijd de ui en de wortels in kleine blokjes en bak ze 4 minuten zacht in de olijfolie","Voeg het kalkoengehakt toe en bak het 5 minuten bruin; roer dan de gehakte knoflook en de oregano erdoor","Voeg de tomatenblokjes toe en laat 10 minuten zachtjes koken","Kook intussen de pasta in kokend water met zout, giet af en meng met de saus"],"seasonings":["1 tl gedroogde oregano","zout","zwarte peper"]}}'::jsonb, 187),
  ('l-garlic-shrimp-spaghetti', 'Garlic Chili Shrimp Spaghetti', 'Spaghetti with shrimp, garlic, chili, tomato and spinach', 'lunch', 'shrimp', '🍤', 15, 'quick', 540, 39, 65, 14, 5, 5, 198, '[{"name":"shrimp","amount":130,"unit":"g"},{"name":"pasta","amount":75,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"tomato","amount":100,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","salt","squeeze of lemon juice"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain, keeping a little of the water","Warm the olive oil in a pan and gently fry the sliced garlic and chili flakes for 1 minute","Add the shrimp and diced tomato and cook for 3 minutes until the shrimp are pink","Toss in the pasta, spinach and a splash of pasta water and finish with lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["italian","spicy","quick","light","shrimp","pasta","garlic","tomato","spinach","olive oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Спагети със скариди, чесън и чили","description":"Спагети със скариди, чесън, чили, домат и спанак","instructions":["Сварете пастата в подсолена вряща вода според указанията на опаковката и я отцедете, като запазите малко от водата","Затоплете зехтина в тиган и запържете леко нарязания чесън и люспите чили за 1 минута","Добавете скаридите и нарязания на кубчета домат и гответе 3 минути, докато скаридите порозовеят","Добавете пастата, спанака и малко от водата от пастата, разбъркайте и овкусете с лимонов сок"],"seasonings":["1/2 ч.л. люспи чили","сол","няколко капки лимонов сок"]},"nl":{"name":"Spaghetti met garnalen, knoflook en chili","description":"Spaghetti met garnalen, knoflook, chili, tomaat en spinazie","instructions":["Kook de pasta in kokend water met zout volgens de verpakking en giet af; bewaar een beetje kookvocht","Verwarm de olijfolie in een pan en bak de plakjes knoflook en de chilivlokken 1 minuut zachtjes","Voeg de garnalen en de tomatenblokjes toe en bak 3 minuten tot de garnalen roze zijn","Schep de pasta, de spinazie en een scheutje kookvocht erdoor en maak af met citroensap"],"seasonings":["1/2 tl chilivlokken","zout","kneepje citroensap"]}}'::jsonb, 188),
  ('l-salmon-pesto-pasta', 'Salmon and Pea Pesto Pasta', 'Pasta with flaked salmon, peas and pesto', 'lunch', 'salmon', '🐟', 20, 'quick', 594, 34, 57, 24, 5, 5, 322, '[{"name":"salmon","amount":110,"unit":"g"},{"name":"pasta","amount":65,"unit":"g"},{"name":"pesto","amount":20,"unit":"g"},{"name":"peas","amount":50,"unit":"g"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet, adding the peas for the last 2 minutes, then drain","Fry the salmon in a non-stick pan over medium heat for 3 to 4 minutes per side, then break it into flakes","Toss the pasta and peas with the pesto and fold in the salmon","Season with pepper and lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","salmon","pasta","pesto","peas","stovetop","lunch"]'::jsonb, '["halal","kosher"]'::jsonb, '{"bg":{"name":"Паста с песто, сьомга и грах","description":"Паста с парченца сьомга, грах и песто","instructions":["Сварете пастата в подсолена вряща вода според указанията на опаковката, като през последните 2 минути добавите граха, и отцедете","Изпържете сьомгата в незалепващ тиган на среден огън по 3–4 минути от всяка страна, след което я разделете на парченца","Разбъркайте пастата и граха с пестото и добавете внимателно сьомгата","Овкусете с пипер и лимонов сок"],"seasonings":["сол","черен пипер","няколко капки лимонов сок"]},"nl":{"name":"Pestopasta met zalm en doperwten","description":"Pasta met stukjes zalm, doperwten en pesto","instructions":["Kook de pasta in kokend water met zout volgens de verpakking, kook de doperwten de laatste 2 minuten mee en giet af","Bak de zalm 3 tot 4 minuten per kant in een koekenpan met antiaanbaklaag op middelhoog vuur en trek hem dan in stukjes","Meng de pasta en de doperwten met de pesto en schep de zalm erdoor","Breng op smaak met peper en citroensap"],"seasonings":["zout","zwarte peper","kneepje citroensap"]}}'::jsonb, 189),
  ('l-roasted-vegetable-chickpea-pasta', 'Vegetable and Chickpea Pasta', 'Pasta with zucchini, peppers and chickpeas in tomato sauce', 'lunch', 'chickpeas', '🍝', 25, 'balanced', 534, 19, 90, 13, 13, 17, 295, '[{"name":"chickpeas","amount":100,"unit":"g"},{"name":"pasta","amount":65,"unit":"g"},{"name":"zucchini","amount":100,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato sauce","amount":120,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain","Dice the zucchini and peppers and fry them in the olive oil over medium-high heat for 7 minutes until soft and browned","Add the drained chickpeas, tomato sauce and oregano and simmer for 5 minutes","Toss with the pasta and season"]'::jsonb, '["stovetop"]'::jsonb, '["italian","light","chickpeas","pasta","zucchini","peppers","tomato sauce","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Паста със зеленчуци и нахут","description":"Паста с тиквичка, чушки и нахут в доматен сос","instructions":["Сварете пастата в подсолена вряща вода според указанията на опаковката и я отцедете","Нарежете тиквичката и чушките на кубчета и ги запържете в зехтина на умерено силен огън за 7 минути, докато омекнат и се зачервят","Добавете отцедения нахут, доматения сос и ригана и варете на тих огън 5 минути","Разбъркайте с пастата и овкусете"],"seasonings":["1 ч.л. сух риган","сол","черен пипер"]},"nl":{"name":"Pasta met groenten en kikkererwten","description":"Pasta met courgette, paprika en kikkererwten in tomatensaus","instructions":["Kook de pasta in kokend water met zout volgens de verpakking en giet af","Snijd de courgette en de paprika in blokjes en bak ze 7 minuten in de olijfolie op middelhoog tot hoog vuur zacht en bruin","Voeg de uitgelekte kikkererwten, de tomatensaus en de oregano toe en laat 5 minuten zachtjes koken","Meng met de pasta en breng op smaak"],"seasonings":["1 tl gedroogde oregano","zout","zwarte peper"]}}'::jsonb, 190),
  ('l-chicken-caprese-salad', 'Chicken Caprese Salad', 'Sliced chicken with mozzarella, tomato, lettuce and pesto', 'lunch', 'chicken', '🥗', 15, 'quick', 479, 45, 10, 28, 3, 5, 511, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"mozzarella","amount":60,"unit":"g"},{"name":"tomato","amount":150,"unit":"g"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"pesto","amount":15,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Season the chicken and fry it in the olive oil over medium heat for 5 to 6 minutes per side until cooked through, then slice","Slice the tomato and mozzarella and arrange them over the lettuce","Top with the chicken and spoon over the pesto"]'::jsonb, '["stovetop"]'::jsonb, '["italian","fresh","quick","light","chicken","mozzarella","tomato","lettuce","pesto","olive oil","stovetop","lunch"]'::jsonb, '["gluten-free","halal"]'::jsonb, '{"bg":{"name":"Салата „Капрезе“ с пилешко","description":"Нарязано пилешко с моцарела, домат, маруля и песто","instructions":["Овкусете пилешкото и го изпържете в зехтина на среден огън по 5–6 минути от всяка страна, докато се сготви, след което го нарежете","Нарежете домата и моцарелата на резени и ги подредете върху марулята","Сложете пилешкото отгоре и полейте с пестото"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Salade caprese met kip","description":"Plakjes kip met mozzarella, tomaat, sla en pesto","instructions":["Kruid de kip en bak hem in de olijfolie op middelhoog vuur 5 tot 6 minuten per kant gaar; snijd hem dan in plakken","Snijd de tomaat en de mozzarella in plakjes en verdeel ze over de sla","Leg de kip erop en schep de pesto erover"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 191),
