  ('l-tuna-chickpea-salad', 'Tuna and Chickpea Salad', 'No-cook salad of tuna, chickpeas, tomato and cucumber with lemon', 'lunch', 'tuna', '🥗', 10, 'quick', 372, 29, 38, 14, 10, 11, 503, '[{"name":"tuna","amount":100,"unit":"g"},{"name":"chickpeas","amount":100,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"onion","amount":20,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper","handful of fresh parsley"]'::jsonb, '["Drain the tuna and chickpeas","Dice the tomato and cucumber and slice the onion very thinly","Toss everything with the olive oil, the juice of the lemon, salt, pepper and chopped parsley"]'::jsonb, '[]'::jsonb, '["mediterranean","fresh","quick","light","tuna","chickpeas","tomato","cucumber","onion","olive oil","lemon","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Салата с риба тон и нахут","description":"Салата без готвене от риба тон, нахут, домат и краставица с лимон","instructions":["Отцедете рибата тон и нахута","Нарежете домата и краставицата на кубчета, а лука на много тънки резени","Разбъркайте всичко със зехтина, сока от лимона, сол, пипер и нарязания магданоз"],"seasonings":["сол","черен пипер","шепа пресен магданоз"]},"nl":{"name":"Salade met tonijn en kikkererwten","description":"Salade zonder koken van tonijn, kikkererwten, tomaat en komkommer met citroen","instructions":["Laat de tonijn en de kikkererwten uitlekken","Snijd de tomaat en de komkommer in blokjes en de ui in flinterdunne ringen","Meng alles met de olijfolie, het sap van de citroen, zout, peper en de gehakte peterselie"],"seasonings":["zout","zwarte peper","handje verse peterselie"]}}'::jsonb, 196),
  ('l-lemony-lentil-soup', 'Lemony Lentil Soup', 'Smooth-ish lentil and carrot soup with spinach and lemon', 'lunch', 'lentils', '🍋', 30, 'balanced', 419, 22, 68, 10, 15, 11, 205, '[{"name":"lentils","amount":70,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"chopped tomatoes","amount":100,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1 tsp ground cumin","1 stock cube","{450} ml water","black pepper"]'::jsonb, '["Dice the onion and carrots and soften them in the olive oil for 5 minutes, then add the chopped garlic and cumin","Add the rinsed lentils, chopped tomatoes, water and stock cube and simmer for 20 minutes until the lentils are soft","Stir in the spinach until wilted","Add the juice of the lemon and black pepper"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","comfort","light","lentils","carrots","onion","chopped tomatoes","spinach","garlic","olive oil","lemon","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Супа от леща с лимон","description":"Почти гладка супа от леща и моркови със спанак и лимон","instructions":["Нарежете лука и морковите на кубчета и ги задушете в зехтина за 5 минути, след което добавете накълцания чесън и кимиона","Добавете измитата леща, нарязаните домати, водата и кубчето бульон и варете на тих огън 20 минути, докато лещата омекне","Добавете спанака и бъркайте, докато омекне","Добавете сока от лимона и черен пипер"],"seasonings":["1 ч.л. смлян кимион","1 кубче бульон","{450} мл вода","черен пипер"]},"nl":{"name":"Linzensoep met citroen","description":"Vrij gladde soep van linzen en wortel met spinazie en citroen","instructions":["Snijd de ui en de wortels in blokjes en bak ze 5 minuten zacht in de olijfolie; voeg da