  ('l-chicken-gyros-wrap', 'Chicken Gyros Wrap', 'Oregano chicken in a tortilla with yogurt, cucumber, tomato and onion', 'lunch', 'chicken', '🌯', 15, 'quick', 460, 40, 38, 16, 3, 8, 523, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"greek yogurt","amount":50,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"onion","amount":20,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","1/2 tsp paprika","salt","squeeze of lemon juice"]'::jsonb, '["Cut the chicken into thin strips, toss with the oregano, paprika and salt and fry in the olive oil over high heat for 5 to 6 minutes","Slice the cucumber, tomato and onion","Warm the tortilla, spread it with the yogurt and fill with the chicken and vegetables","Squeeze over lemon juice and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","light","chicken","tortilla","greek yogurt","cucumber","tomato","onion","olive oil","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Врап с пилешки гирос","description":"Пилешко с риган в тортила с кисело мляко, краставица, домат и лук","instructions":["Нарежете пилешкото на тънки ивици, овкусете го с ригана, червения пипер и сол и го запържете в зехтина на силен огън за 5–6 минути","Нарежете краставицата, домата и лука на резени","Затоплете тортилата, намажете я с киселото мляко и я напълнете с пилешкото и зеленчуците","Изстискайте лимонов сок и навийте"],"seasonings":["1 ч.л. сух риган","1/2 ч.л. червен пипер","сол","няколко капки лимонов сок"]},"nl":{"name":"Gyroswrap met kip","description":"Kip met oregano in een tortilla met yoghurt, komkommer, tomaat en ui","instructions":["Snijd de kip in dunne reepjes, meng ze met de oregano, het paprikapoeder en zout en bak ze 5 tot 6 minuten in de olijfolie op hoog vuur","Snijd de komkommer, de tomaat en de ui in plakjes","Verwarm de tortilla, bes