  ('l-quinoa-greek-salad', 'Quinoa Greek Salad', 'Quinoa with chickpeas, feta, cucumber, tomato and peppers', 'lunch', 'chickpeas', '🥗', 20, 'quick', 531, 21, 65, 22, 11, 9, 616, '[{"name":"quinoa","amount":60,"unit":"g"},{"name":"chickpeas","amount":60,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"cucumber","amount":100,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"peppers","amount":50,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","squeeze of lemon juice","salt"]'::jsonb, '["Rinse the quinoa and simmer it in salted water for 12 to 15 minutes, then drain and let it cool a little","Dice the cucumber, tomato and peppers","Toss the quinoa with the vegetables, drained chickpeas, olive oil, oregano and lemon juice","Crumble the feta over the top"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","quick","light","quinoa","chickpeas","feta","cucumber","tomato","peppers","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Гръцка салата с киноа","description":"Киноа с нахут, фета, краставица, домат и чушки","instructions":["Измийте киноата и я варете в подсолена вода на тих огън 12–15 минути, след което я отцедете и я оставете леко да изстине","Нарежете краставицата, домата и чушките на кубчета","Разбъркайте киноата със зеленчуците, отцедения нахут, зехтина, ригана и лимоновия сок","Натрошете фетата отгоре"],"seasonings":["1 ч.л. сух риган","няколко капки лимонов сок","сол"]},"nl":{"name":"Griekse quinoasalade","description":"Quinoa met kikkererwten, feta, komkommer, tomaat en paprika","instructions":["Spoel de quinoa af en laat hem 12 tot 15 minuten zachtjes koken in water met zout; giet af en laat iets afkoelen","Snijd de komkommer, de tomaat en de paprika in blokjes","Meng de quinoa met de groenten, de uitgelekte kikkererwten, de olijfolie, de oregano en het citroensap","Verkruimel de feta erover"],"seasonings":["1 tl gedroogde oregano","kneepje citroensap","zout"]}}'::jsonb, 200),
  ('l-spanish-omelette', 'Spanish Potato Omelette', 'Thick omelette of potato and onion cooked in olive oil', 'lunch', 'eggs', '🥔', 30, 'balanced', 520, 25, 42, 28, 5, 5, 249, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Cut the potatoes into thin slices and slice the onion","Cook them gently in the olive oil in a small non-stick pan, covered, for 12 to 15 minutes until soft but not browned","Beat the eggs with salt and pepper, stir in the potatoes and onion, and pour everything back into the pan","Cook over low heat for 5 minutes, flip using a plate and cook 3 more minutes until set"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","light","eggs","potatoes","onion","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Испански омлет с картофи","description":"Дебел омлет от картофи и лук, приготвен в зехтин","instructions":["Нарежете картофите на тънки резени, а лука на филийки","Гответе ги в зехтина на слаб огън в малък незалепващ тиган под капак 12–15 минути, докато омекнат, без да се зачервят","Разбийте яйцата със сол и пипер, добавете картофите и лука и изсипете всичко обратно в тигана","Гответе на слаб огън 5 минути, обърнете с помощта на чиния и гответе още 3 минути, докато стегне"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Spaanse aardappelomelet","description":"Dikke omelet van aardappel en ui, gebakken in olijfolie","instructions":["Snijd de aardappelen in dunne plakjes en de ui in ringen","Bak ze 12 tot 15 minuten zachtjes in de olijfolie in een kleine koekenpan met antiaanbaklaag, met het deksel op de pan, tot ze zacht maar niet bruin zijn","Klop de eieren los met zout en peper, roer de aardappelen en de ui erdoor en giet alles terug in de pan","Bak 5 minuten op laag vuur, keer 