  ('l-mediterranean-tofu-bowl', 'Mediterranean Tofu Couscous Bowl', 'Oregano tofu with zucchini, peppers and tomato over couscous', 'lunch', 'tofu', '🥙', 20, 'quick', 531, 34, 58, 21, 10, 8, 40, '[{"name":"tofu","amount":140,"unit":"g"},{"name":"couscous","amount":55,"unit":"g"},{"name":"zucchini","amount":100,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","{75} ml boiling water","squeeze of lemon juice","salt"]'::jsonb, '["Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Cut the tofu into cubes and fry in the olive oil over medium-high heat for 5 minutes until golden","Add the diced zucchini and peppers with the oregano and cook for 5 minutes","Serve over the couscous with the diced tomato and a squeeze of lemon"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","light","tofu","couscous","zucchini","peppers","tomato","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Средиземноморска купа с тофу и кускус","description":"Тофу с риган, тиквичка, чушки и домат върху кускус","instructions":["Залейте кускуса с врящата вода и щипка сол, покрийте за 5 минути и го разрохкайте с вилица","Нарежете тофуто на кубчета и го запържете в зехтина на умерено силен огън за 5 минути до златисто","Добавете нарязаните на кубчета тиквичка и чушки с ригана и гответе 5 минути","Поднесете върху кускуса с нарязания на кубчета домат и няколко капки лимон"],"seasonings":["1 ч.л. сух риган","{75} мл вряща вода","няколко капки лимонов сок","сол"]},"nl":{"name":"Mediterrane couscousbowl met tofu","description":"Tofu met oregano, courgette, paprika en tomaat op couscous","instructions":["Giet het kokende water over de couscous met een snufje zout, dek 5 minuten af en maak los met een vork","Snijd de tofu in blokjes en bak ze 5 