  ('l-chicken-shawarma-rice-bowl', 'Chicken Shawarma Rice Bowl', 'Spiced chicken over rice with garlic yogurt, cucumber and tomato', 'lunch', 'chicken', '🍗', 25, 'balanced', 663, 46, 76, 18, 2, 6, 99, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"rice","amount":85,"unit":"g"},{"name":"greek yogurt","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","1/2 tsp ground coriander","salt"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Slice the chicken thinly and coat it with the cumin, paprika, chili flakes, coriander and salt","Fry in the olive oil over high heat for 6 minutes until browned at the edges","Serve over the rice with the diced cucumber and tomato and a spoon of yogurt"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","hearty","chicken","rice","greek yogurt","cucumber","tomato","olive oil","stovetop","lunch"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Купа ориз с пилешка шаурма","description":"Пилешко с подправки върху ориз с чесново кисело мляко, краставица и домат","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Нарежете пилешкото на тънки ивици и го овкусете с кимиона, червения пипер, люспите чили, кориандъра и сол","Запържете в зехтина на силен огън за 6 минути, докато се зачерви по краищата","Поднесете върху ориза с нарязаните на кубчета краставица и домат и лъжица кисело мляко"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","1/2 ч.л. люспи чили","1/2 ч.л. смлян кориандър","сол"]},"nl":{"name":"Rijstkom met kipshoarma","description":"Gekruide kip op rijst met knoflookyoghurt, komkommer en tomaat","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Snijd de kip in dunne reepjes en wentel ze door de komijn, het paprikapoeder, de chilivlokke