  ('l-lentil-feta-salad', 'Lentil and Feta Salad', 'Warm lentils with feta, tomato, cucumber and spinach', 'lunch', 'lentils', '🥗', 30, 'balanced', 462, 26, 54, 18, 10, 6, 498, '[{"name":"lentils","amount":70,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["splash of red wine vinegar","salt","black pepper"]'::jsonb, '["Simmer the rinsed lentils in unsalted water for 20 to 25 minutes until tender but still holding their shape, then drain","Dice the tomato and cucumber","Toss the warm lentils with the olive oil, vinegar, salt and pepper, then fold in the spinach, tomato and cucumber","Crumble the feta over the top"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","light","lentils","feta","tomato","cucumber","spinach","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Салата с леща и фета","description":"Топла леща с фета, домат, краставица и спанак","instructions":["Варете измитата леща в неподсолена вода на тих огън 20–25 минути, докато омекне, но запази формата си, и я отцедете","Нарежете домата и краставицата на кубчета","Разбъркайте топлата леща със зехтина, оцета, сол и пипер, след което добавете спанака, домата и краставицата","Натрошете фетата отгоре"],"seasonings":["малко червен винен оцет","сол","черен пипер"]},"nl":{"name":"Salade met linzen en feta","description":"Warme linzen met feta, tomaat, komkommer en spinazie","instructions":["Laat de afgespoelde linzen 20 tot 25 minuten zachtjes koken in water zonder zout tot ze gaar zijn maar nog heel; giet af","Snijd de tomaat en de komkommer in blokjes","Meng de warme linzen met de olijfolie, de azijn, zout en peper en schep dan de spinazie, de tomaat en de komkommer erdoor","Verkruimel de feta erover"],"seasonings":["scheutje rodewijnazijn","zout","zwarte peper"]}}'::jsonb, 206),
  ('l-chicken-salad-wrap', 'Chicken Salad Wrap', 'Tortilla with chicken, lettuce, tomato, cucumber and a yogurt dressing', 'lunch', 'chicken', '🌯', 15, 'quick', 379, 35, 37, 10, 4, 7, 522, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"cucumber","amount":50,"unit":"g"},{"name":"yogurt","amount":40,"unit":"g"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Season the chicken and fry it in a non-stick pan over medium heat for 5 to 6 minutes per side, then slice","Stir the mustard and a pinch of salt into the yogurt","Shred the lettuce and slice the tomato and cucumber","Spread the yogurt over the tortilla, add the chicken and vegetables and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","chicken","tortilla","lettuce","tomato","cucumber","yogurt","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Врап с пилешка салата","description":"Тортила с пилешко, маруля, домат, краставица и дресинг от кисело мляко","instructions":["Овкусете пилешкото и го изпържете в незалепващ тиган на среден огън по 5–6 минути от всяка страна, след което го нарежете","Разбъркайте горчицата и щипка сол в киселото мляко","Нарежете марулята на ивици, а домата и краставицата на резени","Намажете киселото мляко върху тортилата, добавете пилешкото и зеленчуците и навийте"],"seasonings":["1 ч.л. горчица","сол","черен пипер"]},"nl":{"name":"Wrap met kipsalade","description":"Tortilla met kip, sla, tomaat, komkommer en een yoghurtdressing","instructions":["Kruid de kip en bak hem in een koekenpan met antiaanbaklaag op middelhoog vuur 5 tot 6 minuten per kant; snijd hem dan in plakken","Roer de mosterd en een snufje zout door de yoghurt","Snijd de sla in reepjes en de tomaat en de komkommer in plakjes","Smeer de yoghurt over de tortilla, leg de kip en de groenten erop en rol op"],"seasonings":["1 tl mosterd","zout","zwarte peper"]}}'::jsonb, 207),
  ('l-egg-salad-sandwich', 'Egg Salad Sandwich', 'Chopped egg in a mustard yogurt dressing with lettuce and cucumber', 'lunch', 'eggs', '🥪', 15, 'quick', 365, 24, 35, 14, 5, 6, 492, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"yogurt","amount":30,"unit":"g"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"cucumber","amount":50,"unit":"g"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Boil the eggs for 9 minutes, cool them under cold water and peel","Chop the eggs and mix with the yogurt, mustard, salt and pepper","Pile onto one slice of bread with the lettuce and sliced cucumber and top with the second slice"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","eggs","bread","yogurt","lettuce","cucumber","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Сандвич с яйчена салата","description":"Нарязани яйца в дресинг от горчица и кисело мляко с маруля и краставица","instructions":["Сварете яйцата за 9 минути, охладете ги под студена вода и ги обелете","Нарежете яйцата и ги смесете с киселото мляко, горчицата, сол и пипер","Сложете сместа върху едната филийка с марулята и нарязаната краставица и покрийте с втората филийка"],"seasonings":["1 ч.л. горчица","сол","черен пипер"]},"nl":{"name":"Sandwich met eiersalade","description":"Gehakt ei in een dressing van mosterd en yoghurt met sla en komkommer","instructions":["Kook de eieren 9 minuten, laat ze schrikken onder koud water en pel ze","Hak de eieren en meng ze met de yoghurt, de mosterd, zout en peper","Schep op één sneetje brood met de sla en de plakjes komkommer en leg het tweede sneetje erop"],"seasonings":["1 tl mosterd","zout","zwarte peper"]}}'::jsonb, 208),
  ('l-tuna-melt-toastie', 'Tuna Melt Toastie', 'Pan-toasted sandwich with tuna, corn and melted cheese', 'lunch', 'tuna', '🥪', 10, 'quick', 423, 35, 36, 16, 5, 5, 901, '[{"name":"tuna","amount":90,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"cheese","amount":30,"unit":"g"},{"name":"corn","amount":40,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Mix the drained tuna with the corn and pepper","Butter one side of each slice of bread and put one slice butter side down in a pan","Top with the tuna and grated cheese and the second slice, butter side up","Toast over medium heat for 2 to 3 minutes per side until golden and the cheese has melted"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","tuna","bread","cheese","corn","butter","stovetop","lunch"]'::jsonb, '["nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Тост с риба тон и разтопен кашкавал","description":"Запечен в тиган сандвич с риба тон, царевица и разтопен кашкавал","instructions":["Смесете отцедената риба тон с царевицата и пипер","Намажете едната страна на всяка филийка с масло и сложете едната филийка в тиган с маслото надолу","Сложете отгоре рибата тон и настъргания кашкавал и втората филийка с маслото нагоре","Запечете на среден огън по 2–3 минути от всяка страна, докато стане златист и кашкавалът се разтопи"],"seasonings":["черен пипер"]},"nl":{"name":"Tosti tuna melt","description":"In de pan gebakken tosti met tonijn, mais en gesmolten kaas","instructions":["Meng de uitgelekte tonijn met de mais en peper","Besmeer één kant van elk sneetje brood met boter en leg één sneetje met de boterkant naar beneden in een pan","Leg de tonijn en de geraspte kaas erop en dan het tweede sneetje, met de boterkant naar boven","Bak op middelhoog vuur 2 tot 3 minuten per kant, tot de tosti goudbruin is en de kaas gesmolten is"],"seasonings":["zwarte peper"]}}'::jsonb, 209),
  ('l-stuffed-sweet-potato-chickpeas', 'Stuffed Sweet Potato with Chickpeas', 'Baked sweet potato filled with spiced chickpeas and spinach', 'lunch', 'chickpeas', '🍠', 15, 'quick', 507, 15, 89, 12, 18, 18, 500, '[{"name":"sweet potato","amount":300,"unit":"g"},{"name":"chickpeas","amount":120,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1/2 tsp smoked paprika","1/2 tsp ground cumin","salt","squeeze of lemon juice"]'::jsonb, '["Prick the sweet potato all over and microwave on high for 8 to 10 minutes, turning once, until soft","Warm the drained chickpeas in the olive oil with the paprika, cumin and salt for 3 minutes","Stir in the spinach until it wilts","Split the sweet potato, fill it with the chickpeas and finish with lemon juice"]'::jsonb, '["stovetop","microwave"]'::jsonb, '["comfort","quick","light","sweet potato","chickpeas","spinach","olive oil","stovetop","microwave","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пълнен сладък картоф с нахут","description":"Печен сладък картоф, пълнен с нахут с подправки и спанак","instructions":["Надупчете сладкия картоф от всички страни и го пригответе в микровълновата на висока мощност 8–10 минути, като го обърнете веднъж, докато омекне","Затоплете отцедения нахут в зехтина с червения пипер, кимиона и сол за 3 минути","Добавете спанака и бъркайте, докато омекне","Разрежете сладкия картоф, напълнете го с нахута и овкусете с лимонов сок"],"seasonings":["1/2 ч.л. пушен червен пипер","1/2 ч.л. смлян кимион","сол","няколко капки лимонов сок"]},"nl":{"name":"Gevulde zoete aardappel met kikkererwten","description":"Gepofte zoete aardappel gevuld met gekruide kikkererwten en spinazie","instructions":["Prik de zoete aardappel rondom in en gaar hem 8 tot 10 minuten in de magnetron op de hoogste stand; keer één keer, tot hij zacht is","Verwarm de uitgelekte kikkererwten 3 minuten in de olijfolie met het paprikapoeder, de komijn en zout","Roer de spinazie erdoor tot hij slinkt","Snijd de zoete aardappel open, vul hem met de kikkererwten en maak af met citroensap"],"seasonings":["1/2 tl gerookt paprikapoeder","1/2 tl gemalen komijn","zout","kneepje citroensap"]}}'::jsonb, 210),
  ('l-chicken-vegetable-soup', 'Chicken and Vegetable Soup', 'Clear soup with chicken, potato, carrot and peas', 'lunch', 'chicken', '🍲', 30, 'balanced', 407, 36, 45, 9, 8, 10, 179, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"potatoes","amount":150,"unit":"g"},{"name":"carrots","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 stock cube","{500} ml water","black pepper","handful of fresh parsley"]'::jsonb, '["Dice the onion and soften it in the oil in a pot for 3 minutes","Add the diced potatoes and carrots, the water, stock cube and the whole piece of chicken and simmer for 18 minutes","Lift out the chicken, shred it with two forks and return it to the pot with the peas","Cook 2 more minutes and season with pepper and parsley"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","light","chicken","potatoes","carrots","onion","peas","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пилешка супа със зеленчуци","description":"Бистра супа с пилешко, картофи, моркови и грах","instructions":["Нарежете лука на кубчета и го задушете в олиото в тенджера за 3 минути","Добавете нарязаните на кубчета картофи и моркови, водата, кубчето бульон и цялото парче пилешко и варете на тих огън 18 минути","Извадете пилешкото, накъсайте го с две вилици и го върнете в тенджерата заедно с граха","Варете още 2 минути и овкусете с пипер и магданоз"],"seasonings":["1 кубче бульон","{500} мл вода","черен пипер","шепа пресен магданоз"]},"nl":{"name":"Kippensoep met groenten","description":"Heldere soep met kip, aardappel, wortel en doperwten","instructions":["Snijd de ui in blokjes en bak hem 3 minuten zacht in de olie in een pan","Voeg de blokjes aardappel en wortel, het water, het bouillonblokje en het hele stuk kip toe en laat 18 minuten zachtjes koken","Haal de kip eruit, trek hem met twee vorken uit elkaar en doe hem met de doperwten terug in de pan","Kook nog 2 minuten en breng op smaak met peper en peterselie"],"seasonings":["1 bouillonblokje","{500} ml water","zwarte peper","handje verse peterselie"]}}'::jsonb, 211),
  ('l-ham-cheese-spinach-omelette', 'Ham, Cheese and Spinach Omelette', 'Three-egg omelette with ham, cheese and spinach, with toast', 'lunch', 'eggs', '🧀', 10, 'quick', 542, 40, 20, 33, 4, 3, 1029, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"ham","amount":40,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"butter","amount":5,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["black pepper"]'::jsonb, '["Beat the eggs with pepper, cut the ham into strips and grate the cheese","Melt the butter in a non-stick pan, wilt the spinach for 30 seconds and pour in the eggs","When almost set, scatter the ham and cheese over one half and fold over","Cook 1 more minute and serve with the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","eggs","ham","cheese","spinach","butter","bread","stovetop","lunch"]'::jsonb, '["nut-allergy"]'::jsonb, '{"bg":{"name":"Омлет с шунка, кашкавал и спанак","description":"Омлет от три яйца с шунка, кашкавал и спанак, с препечен хляб","instructions":["Разбийте яйцата с пипер, нарежете шунката на ивици и настържете кашкавала","Разтопете маслото в незалепващ тиган, задушете спанака за 30 секунди и изсипете яйцата","Когато почти стегнат, поръсете шунката и кашкавала върху едната половина и сгънете","Гответе още 1 минута и поднесете с препечения хляб"],"seasonings":["черен пипер"]},"nl":{"name":"Omelet met ham, kaas en spinazie","description":"Omelet van drie eieren met ham, kaas en spinazie, met toast","instructions":["Klop de eieren los met peper, snijd de ham in reepjes en rasp de kaas","Smelt de boter in een koekenpan met antiaanbaklaag, laat de spinazie 30 seconden slinken en giet de eieren erin","Strooi de ham en de kaas over één helft als het ei bijna gestold is en klap dicht","Bak nog 1 minuut en serveer met het geroosterde brood"],"seasonings":["zwarte peper"]}}'::jsonb, 212),
  ('l-warm-salmon-potato-salad', 'Warm Salmon and Potato Salad', 'Flaked salmon with potatoes and green beans in a lemon yogurt dressing', 'lunch', 'salmon', '🥔', 25, 'balanced', 514, 32, 48, 23, 8, 8, 107, '[{"name":"salmon","amount":120,"unit":"g"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"green beans","amount":80,"unit":"g"},{"name":"yogurt","amount":40,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes, adding the green beans for the last 5, then drain","Fry the salmon in the olive oil over medium heat for 3 to 4 minutes per side and break into flakes","Mix the yogurt with the mustard, the juice of the lemon, salt and pepper","Toss the warm potatoes and beans in the dressing and fold in the salmon"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","light","salmon","potatoes","green beans","yogurt","olive oil","lemon","stovetop","lunch"]'::jsonb, '["gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Топла салата със сьомга и картофи","description":"Парченца сьомга с картофи и зелен фасул в дресинг от лимон и кисело мляко","instructions":["Сварете картофите, нарязани на парчета, в подсолена вода за 15 минути, като през последните 5 добавите зеления фасул, и отцедете","Изпържете сьомгата в зехтина на среден огън по 3–4 минути от всяка страна и я разделете на парченца","Смесете киселото мляко с горчицата, сока от лимона, сол и пипер","Разбъркайте топлите картофи и фасула с дресинга и добавете внимателно сьомгата"],"seasonings":["1 ч.л. горчица","сол","черен пипер"]},"nl":{"name":"Warme salade met zalm en aardappel","description":"Stukjes zalm met aardappelen en sperziebonen in een dressing van citroen en yoghurt","instructions":["Kook de aardappelen, in stukken gesneden, 15 minuten in water met zout, kook de sperziebonen de laatste 5 minuten mee en giet af","Bak de zalm 3 tot 4 minuten per kant in de olijfolie op middelhoog vuur en trek hem in stukjes","Meng de yoghurt met de mosterd, het sap van de citroen, zout en peper","Schep de warme aardappelen en bonen door de dressing en schep de zalm erdoor"],"seasonings":["1 tl mosterd","zout","zwarte peper"]}}'::jsonb, 213),
  ('l-turkey-bacon-avocado-sandwich', 'Turkey, Bacon and Avocado Sandwich', 'Toasted sandwich with turkey, crisp bacon, avocado and tomato', 'lunch', 'turkey', '🥪', 15, 'quick', 627, 39, 45, 35, 15, 6, 595, '[{"name":"turkey","amount":100,"unit":"g"},{"name":"bacon","amount":25,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":60,"unit":"g"},{"name":"lettuce","amount":20,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Fry the bacon in a dry pan over medium heat for 4 minutes until crisp and set it aside","Slice the turkey thinly, season and fry it in the bacon fat for 4 minutes until cooked through","Toast the bread and spread it with the mashed avocado","Layer on the turkey, bacon, sliced tomato and lettuce"]'::jsonb, '["stovetop"]'::jsonb, '["quick","turkey","bacon","bread","avocado","tomato","lettuce","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Сандвич с пуешко, бекон и авокадо","description":"Препечен сандвич с пуешко, хрупкав бекон, авокадо и домат","instructions":["Изпържете бекона в сух тиган на среден огън за 4 минути, докато стане хрупкав, и го оставете настрани","Нарежете пуешкото на тънки резени, овкусете го и го изпържете в мазнината от бекона за 4 минути, докато се сготви","Препечете хляба и го намажете с намачканото авокадо","Наредете пуешкото, бекона, нарязания домат и марулята"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Sandwich met kalkoen, spek en avocado","description":"Geroosterde sandwich met kalkoen, knapperig spek, avocado en tomaat","instructions":["Bak het spek 4 minuten in een droge pan op middelhoog vuur knapperig en leg het apart","Snijd de kalkoen in dunne plakjes, kruid ze en bak ze 4 minuten in het spekvet tot ze gaar zijn","Rooster het brood en besmeer het met de geprakte avocado","Beleg met de kalkoen, het spek, de plakjes tomaat en de sla"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 214),
  ('l-chicken-quinoa-bowl', 'Chicken Quinoa Bowl', 'Quinoa with chicken, broccoli and carrot in a lemon olive oil dressing', 'lunch', 'chicken', '🥗', 20, 'quick', 519, 42, 56, 16, 10, 6, 130, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"quinoa","amount":60,"unit":"g"},{"name":"broccoli","amount":100,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Rinse the quinoa and simmer it in salted water for 12 to 15 minutes, adding the broccoli florets for the last 3, then drain","Season the chicken and fry it in half the olive oil for 5 to 6 minutes per side, then slice","Grate the carrots","Serve the quinoa and broccoli topped with the chicken and carrots, dressed with the remaining olive oil and the juice of the lemon"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","chicken","quinoa","broccoli","carrots","olive oil","lemon","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа с киноа и пилешко","description":"Киноа с пилешко, броколи и морков в дресинг от лимон и зехтин","instructions":["Измийте киноата и я варете в подсолена вода на тих огън 12–15 минути, като през последните 3 добавите розичките броколи, и отцедете","Овкусете пилешкото и го изпържете в половината зехтин по 5–6 минути от всяка страна, след което го нарежете","Настържете морковите","Поднесете киноата и броколите с пилешкото и морковите отгоре, овкусени с останалия зехтин и сока от лимона"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Quinoabowl met kip","description":"Quinoa met kip, broccoli en wortel in een dressing van citroen en olijfolie","instructions":["Spoel de quinoa af en laat hem 12 tot 15 minuten zachtjes koken in water met zout; kook de broccoliroosjes de laatste 3 minuten mee en giet af","Kruid de kip en bak hem in de helft van de olijfolie 5 tot 6 minuten per kant; snijd hem dan in plakken","Rasp de wortels","Serveer de quinoa en de broccoli met de kip en de wortels erop, aangemaakt met de rest van de olijfolie en het sap van de citroen"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 215),
  ('l-beef-potato-hash', 'Beef and Potato Hash', 'Skillet of beef mince, crisp potatoes, onion and peas', 'lunch', 'beef mince', '🥔', 25, 'balanced', 580, 30, 55, 27, 8, 7, 150, '[{"name":"beef mince","amount":120,"unit":"g"},{"name":"potatoes","amount":250,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp paprika","salt","black pepper"]'::jsonb, '["Cut the potatoes into 1 cm cubes and fry them in the oil over medium heat for 12 minutes, turning, until golden and tender","Push them aside, add the beef mince and diced onion and brown for 6 minutes","Stir in the peas, paprika, salt and pepper and cook 2 more minutes"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","beef mince","potatoes","onion","peas","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Хаш с телешка кайма и картофи","description":"Тиган с телешка кайма, хрупкави картофи, лук и грах","instructions":["Нарежете картофите на кубчета от 1 см и ги пържете в олиото на среден огън 12 минути, като ги обръщате, докато станат златисти и меки","Избутайте ги настрани, добавете телешката кайма и нарязания на кубчета лук и запържете 6 минути","Добавете граха, червения пипер, сол и пипер и гответе още 2 минути"],"seasonings":["1 ч.л. червен пипер","сол","черен пипер"]},"nl":{"name":"Hash van rundergehakt en aardappel","description":"Pannetje met rundergehakt, knapperige aardappelen, ui en doperwten","instructions":["Snijd de aardappelen in blokjes van 1 cm en bak ze 12 minuten in de olie op middelhoog vuur goudbruin en gaar; keer regelmatig","Schuif ze opzij, voeg het rundergehakt en de blokjes ui toe en bak 6 minuten bruin","Roer de doperwten, het paprikapoeder, zout en peper erdoor en bak nog 2 minuten"],"seasonings":["1 tl paprikapoeder","zout","zwarte peper"]}}'::jsonb, 216),
  ('l-pork-schnitzel-sandwich', 'Pork Schnitzel Sandwich', 'Thin breaded pork cutlet in bread with lettuce', 'lunch', 'pork', '🥪', 20, 'quick', 592, 43, 43, 27, 5, 4, 462, '[{"name":"pork","amount":120,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"flour","amount":15,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["salt","black pepper","1 tsp mustard","squeeze of lemon juice"]'::jsonb, '["Flatten the pork between two sheets of baking paper until about 1 cm thick and season it","Coat it in the flour, then in the beaten egg, then in the flour again","Fry in the oil over medium-high heat for 3 minutes per side until golden and cooked through","Spread the bread with mustard, add the lettuce and schnitzel and squeeze over lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","pork","bread","flour","eggs","lettuce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Сандвич със свински шницел","description":"Тънка панирана свинска пържола в хляб с маруля","instructions":["Начукайте свинското между два листа хартия за печене до дебелина около 1 см и го овкусете","Овалвайте го в брашното, след това в разбитото яйце и отново в брашното","Пържете в олиото на умерено силен огън по 3 минути от всяка страна, докато стане златисто и се сготви","Намажете хляба с горчица, добавете марулята и шницела и изстискайте лимонов сок"],"seasonings":["сол","черен пипер","1 ч.л. горчица","няколко капки лимонов сок"]},"nl":{"name":"Sandwich met varkensschnitzel","description":"Dunne gepaneerde varkenslap op brood met sla","instructions":["Sla het varkensvlees tussen twee vellen bakpapier plat tot het ongeveer 1 cm dik is en kruid het","Wentel het door de bloem, dan door het losgeklopte ei en dan nog eens door de bloem","Bak in de olie op middelhoog tot hoog vuur 3 minuten per kant goudbruin en gaar","Besmeer het brood met mosterd, leg de sla en de schnitzel erop en knijp er citroensap over"],"seasonings":["zout","zwarte peper","1 tl mosterd","kneepje citroensap"]}}'::jsonb, 217),
  ('l-tofu-scramble-wrap', 'Tofu Scramble Wrap', 'Tortilla filled with scrambled tofu, spinach, peppers and tomato', 'lunch', 'tofu', '🌯', 15, 'quick', 482, 33, 42, 23, 9, 7, 508, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"spinach","amount":50,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp turmeric","1/2 tsp ground cumin","salt","black pepper"]'::jsonb, '["Dice the peppers and cook them in the oil for 3 minutes","Crumble in the tofu with the turmeric, cumin, salt and pepper and cook for 5 minutes","Stir in the spinach and diced tomato until the spinach wilts","Warm the tortilla, add the scramble and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","tofu","tortilla","spinach","peppers","tomato","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Врап с бъркано тофу","description":"Тортила с бъркано тофу, спанак, чушки и домат","instructions":["Нарежете чушките на кубчета и ги запържете в олиото за 3 минути","Натрошете тофуто, добавете куркумата, кимиона, сол и пипер и гответе 5 минути","Добавете спанака и нарязания на кубчета домат и бъркайте, докато спанакът омекне","Затоплете тортилата, сложете сместа и навийте"],"seasonings":["1/2 ч.л. куркума","1/2 ч.л. смлян кимион","сол","черен пипер"]},"nl":{"name":"Wrap met roertofu","description":"Tortilla gevuld met roertofu, spinazie, paprika en tomaat","instructions":["Snijd de paprika in blokjes en bak ze 3 minuten in de olie","Verkruimel de tofu erboven, voeg de kurkuma, de komijn, zout en peper toe en bak 5 minuten","Roer de spinazie en de tomatenblokjes erdoor tot de spinazie slinkt","Verwarm de tortilla, leg de roertofu erop en rol op"],"seasonings":["1/2 tl kurkuma","1/2 tl gemalen komijn","zout","zwarte peper"]}}'::jsonb, 218),
  ('l-fish-finger-sandwich', 'Crispy Fish Sandwich', 'Pan-fried breaded white fish in bread with lettuce and lemon yogurt', 'lunch', 'white fish', '🐟', 20, 'quick', 554, 43, 44, 22, 5, 5, 489, '[{"name":"white fish","amount":140,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"flour","amount":15,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"yogurt","amount":30,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice"]'::jsonb, '["Cut the fish into thick strips, season and coat in the flour, then the beaten egg, then the flour again","Fry in the oil over medium-high heat for 2 to 3 minutes per side until golden","Stir lemon juice into the yogurt","Fill the bread with the lettuce, fish and yogurt sauce"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","white fish","bread","flour","eggs","lettuce","yogurt","oil","stovetop","lunch"]'::jsonb, '["nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Сандвич с хрупкава риба","description":"Панирана бяла риба на тиган в хляб с маруля и кисело мляко с лимон","instructions":["Нарежете рибата на дебели ивици, овкусете ги и ги овалвайте в брашното, след това в разбитото яйце и отново в брашното","Пържете в олиото на умерено силен огън по 2–3 минути от всяка страна до златисто","Разбъркайте лимонов сок в киселото мляко","Напълнете хляба с марулята, рибата и соса от кисело мляко"],"seasonings":["сол","черен пипер","няколко капки лимонов сок"]},"nl":{"name":"Sandwich met krokante vis","description":"Gebakken gepaneerde witvis op brood met sla en citroenyoghurt","instructions":["Snijd de vis in dikke repen, kruid ze en wentel ze door de bloem, dan door het losgeklopte ei en dan nog eens door de bloem","Bak in de olie op middelhoog tot hoog vuur 2 tot 3 minuten per kant goudbruin","Roer citroensap door de yoghurt","Beleg het brood met de sla, de vis en de yoghurtsaus"],"seasonings":["zout","zwarte peper","kneepje citroensap"]}}'::jsonb, 219),
  ('l-shrimp-avocado-salad', 'Shrimp and Avocado Salad', 'Quick salad of pan-fried shrimp, avocado, tomato and cucumber with lemon', 'lunch', 'shrimp', '🥗', 10, 'quick', 471, 34, 26, 30, 14, 7, 189, '[{"name":"shrimp","amount":140,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"lettuce","amount":60,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Fry the shrimp in half the olive oil over high heat for 2 to 3 minutes until pink and season","Dice the avocado, tomato and cucumber and tear the lettuce","Toss the salad with the remaining olive oil and the juice of the lemon and top with the shrimp"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","shrimp","avocado","lettuce","tomato","cucumber","olive oil","lemon","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Салата със скариди и авокадо","description":"Бърза салата от запържени скариди, авокадо, домат и краставица с лимон","instructions":["Запържете скаридите в половината зехтин на силен огън за 2–3 минути, докато порозовеят, и ги овкусете","Нарежете авокадото, домата и краставицата на кубчета и накъсайте марулята","Разбъркайте салатата с останалия зехтин и сока от лимона и сложете скаридите отгоре"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Salade met garnalen en avocado","description":"Snelle salade van gebakken garnalen, avocado, tomaat en komkommer met citroen","instructions":["Bak de garnalen 2 tot 3 minuten in de helft van de olijfolie op hoog vuur tot ze roze zijn en breng op smaak","Snijd de avocado, de tomaat en de komkommer in blokjes en scheur de sla","Meng de salade met de rest van de olijfolie en het sap van de citroen en leg de garnalen erop"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 220),
  ('l-chicken-burger', 'Chicken Burger', 'Juicy chicken mince patty in bread with cheese, lettuce and tomato', 'lunch', 'chicken mince', '🍔', 15, 'quick', 508, 39, 34, 24, 6, 5, 572, '[{"name":"chicken mince","amount":140,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp paprika","salt","black pepper","1 tsp mustard"]'::jsonb, '["Mix the chicken mince with the paprika, salt and pepper and shape into a flat patty","Fry in the oil over medium heat for 5 minutes per side until cooked through, laying the cheese on top for the last minute","Toast the bread and spread with mustard","Add the lettuce, patty and sliced tomato"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","chicken mince","bread","lettuce","tomato","cheese","oil","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Пилешки бургер","description":"Сочно кюфте от пилешка кайма в хляб с кашкавал, маруля и домат","instructions":["Смесете пилешката кайма с червения пипер, сол и пипер и оформете плоско кюфте","Пържете в олиото на среден огън по 5 минути от всяка страна, докато се сготви, като през последната минута сложите кашкавала отгоре","Препечете хляба и го намажете с горчица","Добавете марулята, кюфтето и нарязания домат"],"seasonings":["1/2 ч.л. червен пипер","сол","черен пипер","1 ч.л. горчица"]},"nl":{"name":"Kipburger","description":"Sappige burger van kipgehakt op brood met kaas, sla en tomaat","instructions":["Meng het kipgehakt met het paprikapoeder, zout en peper en vorm er een platte burger van","Bak in de olie op middelhoog vuur 5 minuten per kant gaar en leg de kaas er de laatste minuut op","Rooster het brood en besmeer het met mosterd","Beleg met de sla, de burger en de plakjes tomaat"],"seasonings":["1/2 tl paprikapoeder","zout","zwarte peper","1 tl mosterd"]}}'::jsonb, 221),
  ('l-turkey-vegetable-rice-skillet', 'Turkey and Vegetable Rice Skillet', 'One-pan turkey mince with rice, zucchini and peppers in tomato sauce', 'lunch', 'turkey mince', '🍚', 25, 'balanced', 531, 33, 65, 16, 5, 11, 118, '[{"name":"turkey mince","amount":130,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"zucchini","amount":100,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato sauce","amount":100,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp paprika","{200} ml water","salt","black pepper"]'::jsonb, '["Brown the turkey mince in the oil in a lidded pan for 5 minutes","Add the diced zucchini and peppers and the paprika and cook for 3 minutes","Stir in the rice, tomato sauce, water and salt, cover and simmer on low heat for 15 minutes until the rice is tender","Season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["light","turkey mince","rice","zucchini","peppers","tomato sauce","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Ориз с пуешка кайма и зеленчуци на тиган","description":"Ястие в един тиган с пуешка кайма, ориз, тиквичка и чушки в доматен сос","instructions":["Запържете пуешката кайма в олиото в тиган с капак за 5 минути","Добавете нарязаните на кубчета тиквичка и чушки и червения пипер и гответе 3 минути","Добавете ориза, доматения сос, водата и сол, разбъркайте, покрийте и варете на слаб огън 15 минути, докато оризът омекне","Овкусете с пипер"],"seasonings":["1 ч.л. червен пипер","{200} мл вода","сол","черен пипер"]},"nl":{"name":"Rijstpan met kalkoen en groenten","description":"Eenpansgerecht van kalkoengehakt met rijst, courgette en paprika in tomatensaus","instructions":["Bak het kalkoengehakt 5 minuten bruin in de olie in een pan met deksel","Voeg de blokjes courgette en paprika en het paprikapoeder toe en bak 3 minuten","Roer de rijst, de tomatensaus, het water en zout erdoor, dek af en laat 15 minuten op laag vuur zachtjes koken tot de rijst gaar is","Breng op smaak met peper"],"seasonings":["1 tl paprikapoeder","{200} ml water","zout","zwarte peper"]}}'::jsonb, 222),
  ('l-meatball-sandwich', 'Meatball Sandwich', 'Meatballs in tomato sauce with melted cheese in bread', 'lunch', 'mixed mince', '🥪', 20, 'quick', 541, 34, 38, 28, 6, 7, 572, '[{"name":"mixed mince","amount":110,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"tomato sauce","amount":80,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"}]'::jsonb, '["1/2 tsp dried oregano","salt","black pepper"]'::jsonb, '["Season the mixed mince with the oregano, salt and pepper and roll it into {5} small balls","Fry them in a dry non-stick pan for 6 minutes, turning, until browned","Add the tomato sauce and simmer for 5 minutes until the meatballs are cooked through","Spoon onto the bread, top with the grated cheese and close the sandwich"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","mixed mince","bread","tomato sauce","cheese","stovetop","lunch"]'::jsonb, '["nut-allergy"]'::jsonb, '{"bg":{"name":"Сандвич с кюфтенца","description":"Кюфтенца в доматен сос с разтопен кашкавал в хляб","instructions":["Овкусете смесената кайма с ригана, сол и пипер и оформете {5} малки топчета","Запържете ги в сух незалепващ тиган за 6 минути, като ги обръщате, докато се зачервят","Добавете доматения сос и варете на тих огън 5 минути, докато кюфтенцата се сготвят","Сложете върху хляба, поръсете с настъргания кашкавал и затворете сандвича"],"seasonings":["1/2 ч.л. сух риган","сол","черен пипер"]},"nl":{"name":"Sandwich met gehaktballetjes","description":"Gehaktballetjes in tomatensaus met gesmolten kaas op brood","instructions":["Kruid het gemengde gehakt met de oregano, zout en peper en rol er {5} kleine balletjes van","Bak ze 6 minuten in een droge koekenpan met antiaanbaklaag rondom bruin; keer regelmatig","Voeg de tomatensaus toe en laat 5 minuten zachtjes koken tot de balletjes gaar zijn","Schep op het brood, strooi de geraspte kaas erover en klap de sandwich dicht"],"seasonings":["1/2 tl gedroogde oregano","zout","zwarte peper"]}}'::jsonb, 223),
  ('l-egg-potato-green-bean-salad', 'Egg, Potato and Green Bean Salad', 'Warm salad of potatoes, green beans, tomato and boiled eggs', 'lunch', 'eggs', '🥗', 20, 'quick', 445, 20, 46, 21, 8, 7, 178, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"green beans","amount":100,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp mustard","splash of vinegar","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, for 15 minutes, adding the eggs for the last 8 minutes and the green beans for the last 5","Drain, cool the eggs under cold water, peel and quarter them","Whisk the olive oil with the mustard, vinegar, salt and pepper","Toss the potatoes, beans and tomato wedges in the dressing and top with the eggs"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","eggs","potatoes","green beans","tomato","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Салата с яйца, картофи и зелен фасул","description":"Топла салата от картофи, зелен фасул, домат и варени яйца","instructions":["Сварете картофите, нарязани на парчета, за 15 минути, като през последните 8 минути добавите яйцата, а през последните 5 – зеления фасул","Отцедете, охладете яйцата под студена вода, обелете ги и ги нарежете на четвъртинки","Разбийте зехтина с горчицата, оцета, сол и пипер","Разбъркайте картофите, фасула и резените домат с дресинга и сложете яйцата отгоре"],"seasonings":["1 ч.л. горчица","малко оцет","сол","черен пипер"]},"nl":{"name":"Salade met ei, aardappel en sperziebonen","description":"Warme salade van aardappelen, sperziebonen, tomaat en gekookte eieren","instructions":["Kook de aardappelen, in stukken gesneden, 15 minuten; kook de eieren de laatste 8 minuten mee en de sperziebonen de laatste 5","Giet af, laat de eieren schrikken onder koud water, pel ze en snijd ze in vieren","Klop de olijfolie met de mosterd, de azijn, zout en peper","Schep de aardappelen, de bonen en de tomatenpartjes door de dressing en leg de eieren erop"],"seasonings":["1 tl mosterd","scheutje azijn","zout","zwarte peper"]}}'::jsonb, 224),
  ('l-chicken-bacon-corn-chowder', 'Chicken, Bacon and Corn Chowder', 'Creamy soup with chicken, bacon, potato and corn', 'lunch', 'chicken', '🥣', 30, 'balanced', 495, 37, 46, 18, 5, 13, 438, '[{"name":"chicken","amount":110,"unit":"g"},{"name":"bacon","amount":20,"unit":"g"},{"name":"potatoes","amount":150,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"milk","amount":150,"unit":"ml"},{"name":"onion","amount":40,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["1 stock cube","{250} ml water","black pepper"]'::jsonb, '["Fry the chopped bacon with the butter in a pot for 3 minutes, then add the diced onion for 3 minutes","Add the diced potatoes, the chicken in small pieces, the water and stock cube and simmer for 15 minutes","Stir in the corn and milk and heat gently for 3 minutes without boiling","Lightly crush some of the potatoes to thicken and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","light","chicken","bacon","potatoes","corn","milk","onion","butter","stovetop","lunch"]'::jsonb, '["gluten-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Чаудър с пилешко, бекон и царевица","description":"Кремообразна супа с пилешко, бекон, картофи и царевица","instructions":["Запържете нарязания бекон с маслото в тенджера за 3 минути, след което добавете нарязания на кубчета лук за 3 минути","Добавете нарязаните на кубчета картофи, пилешкото на малки парчета, водата и кубчето бульон и варете на тих огън 15 минути","Добавете царевицата и млякото и затоплете леко 3 минути, без да завира","Намачкайте леко част от картофите, за да се сгъсти супата, и овкусете с пипер"],"seasonings":["1 кубче бульон","{250} мл вода","черен пипер"]},"nl":{"name":"Chowder met kip, spek en mais","description":"Romige soep met kip, spek, aardappel en mais","instructions":["Bak het gesneden spek 3 minuten met de boter in een pan en voeg dan de blokjes ui 3 minuten toe","Voeg de blokjes aardappel, de kip in kleine stukjes, het water en het bouillonblokje toe en laat 15 minuten zachtjes koken","Roer de mais en de melk erdoor en verwarm 3 minuten zachtjes zonder te koken","Plet een deel van de aardappelen licht om de soep te binden en breng op smaak met peper"],"seasonings":["1 bouillonblokje","{250} ml water","zwarte peper"]}}'::jsonb, 225),
  ('l-chicken-avocado-rice-bowl', 'Chicken and Avocado Rice Bowl', 'Rice bowl with sliced chicken, avocado, corn and tomato', 'lunch', 'chicken', '🥑', 20, 'quick', 744, 44, 86, 26, 12, 5, 188, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"corn","amount":50,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["squeeze of lime juice","salt","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Season the chicken and fry it in a non-stick pan over medium heat for 5 to 6 minutes per side, then slice","Dice the avocado and tomato","Top the rice with the chicken, avocado, corn and tomato and squeeze over lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","hearty","chicken","rice","avocado","corn","tomato","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа ориз с пилешко и авокадо","description":"Купа ориз с нарязано пилешко, авокадо, царевица и домат","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Овкусете пилешкото и го изпържете в незалепващ тиган на среден огън по 5–6 минути от всяка страна, след което го нарежете","Нарежете авокадото и домата на кубчета","Сложете върху ориза пилешкото, авокадото, царевицата и домата и изстискайте сок от лайм"],"seasonings":["няколко капки сок от лайм","сол","черен пипер"]},"nl":{"name":"Rijstkom met kip en avocado","description":"Rijstkom met plakjes kip, avocado, mais en tomaat","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Kruid de kip en bak hem in een koekenpan met antiaanbaklaag op middelhoog vuur 5 tot 6 minuten per kant; snijd hem dan in plakken","Snijd de avocado en de tomaat in blokjes","Leg de kip, de avocado, de mais en de tomaat op de rijst en knijp er limoensap over"],"seasonings":["kneepje limoensap","zout","zwarte peper"]}}'::jsonb, 226),
  ('l-beef-burger-wedges', 'Beef Burger with Potato Wedges', 'Cheeseburger with lettuce and tomato and oven wedges', 'lunch', 'beef mince', '🍔', 35, 'balanced', 807, 46, 68, 39, 9, 7, 597, '[{"name":"beef mince","amount":150,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"},{"name":"lettuce","amount":20,"unit":"g"},{"name":"tomato","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1/2 tsp paprika","salt","black pepper"]'::jsonb, '["Heat the oven to 220°C, cut the potatoes into wedges, toss with the oil, paprika and salt and roast for 25 minutes, turning once","Season the beef mince, shape it into a patty and fry in a dry pan over medium-high heat for 4 minutes per side","Lay the cheese on the patty for the last minute so it melts","Serve in the bread with the lettuce and sliced tomato, with the wedges on the side"]'::jsonb, '["stovetop","oven"]'::jsonb, '["comfort","hearty","beef mince","bread","potatoes","cheese","lettuce","tomato","oil","stovetop","oven","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Телешки бургер с картофи на фурна","description":"Чийзбургер с маруля и домат и картофи уеджис на фурна","instructions":["Загрейте фурната на 220°C, нарежете картофите на резени тип уеджис, разбъркайте ги с олиото, червения пипер и сол и печете 25 минути, като ги обърнете веднъж","Овкусете телешката кайма, оформете кюфте и го изпържете в сух тиган на умерено силен огън по 4 минути от всяка страна","Сложете кашкавала върху кюфтето през последната минута, за да се разтопи","Поднесете в хляба с марулята и нарязания домат, с картофите отстрани"],"seasonings":["1/2 ч.л. червен пипер","сол","черен пипер"]},"nl":{"name":"Hamburger met aardappelpartjes","description":"Cheeseburger met sla en tomaat en aardappelpartjes uit de oven","instructions":["Verwarm de oven voor op 220°C, snijd de aardappelen in partjes, meng ze met de olie, het paprikapoeder en zout en rooster ze 25 minuten; keer één keer","Kruid het rundergehakt, vorm er een burger van en bak hem in een droge pan op middelhoog tot hoog vuur 4 minuten per kant","Leg de kaas de laatste minuut op de burger zodat hij smelt","Serveer op het brood met de sla en de plakjes tomaat, met de aardappelpartjes ernaast"],"seasonings":["1/2 tl paprikapoeder","zout","zwarte peper"]}}'::jsonb, 227),
  ('l-steak-sandwich', 'Steak and Onion Sandwich', 'Seared beef with soft onions and cheese in toasted bread', 'lunch', 'beef', '🥩', 15, 'quick', 534, 47, 37, 22, 6, 6, 657, '[{"name":"beef","amount":140,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"onion","amount":60,"unit":"g"},{"name":"cheese","amount":25,"unit":"g"},{"name":"butter","amount":8,"unit":"g"},{"name":"lettuce","amount":20,"unit":"g"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Slice the onion and cook it in the butter over medium heat for 6 minutes until soft and golden, then push aside","Season the beef and sear it in the same pan over high heat for 2 minutes per side, rest for 2 minutes and slice thinly","Toast the bread and spread with mustard","Fill with the lettuce, beef, onions and sliced cheese"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","beef","bread","onion","cheese","butter","lettuce","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Сандвич с телешко и лук","description":"Запечатано телешко с мек лук и кашкавал в препечен хляб","instructions":["Нарежете лука на филийки и го гответе в маслото на среден огън 6 минути, докато омекне и стане златист, след което го избутайте настрани","Овкусете телешкото и го запечатайте в същия тиган на силен огън по 2 минути от всяка страна, оставете го да почине 2 минути и го нарежете на тънко","Препечете хляба и го намажете с горчица","Напълнете с марулята, телешкото, лука и нарязания кашкавал"],"seasonings":["1 ч.л. горчица","сол","черен пипер"]},"nl":{"name":"Sandwich met biefstuk en ui","description":"Kort gebakken rundvlees met zachte uien en kaas op geroosterd brood","instructions":["Snijd de ui in ringen en bak hem 6 minuten in de boter op middelhoog vuur zacht en goudbruin; schuif hem dan opzij","Kruid het rundvlees en schroei het in dezelfde pan op hoog vuur 2 minuten per kant dicht, laat 2 minuten rusten en snijd in dunne plakjes","Rooster het brood en besmeer het met mosterd","Beleg met de sla, het vlees, de uien en de plakjes kaas"],"seasonings":["1 tl mosterd","zout","zwarte peper"]}}'::jsonb, 228),
  ('l-pork-apple-salad', 'Pork and Apple Salad', 'Pan-fried pork strips over lettuce with apple, cucumber and a mustard dressing', 'lunch', 'pork', '🍏', 15, 'quick', 478, 34, 45, 19, 8, 22, 235, '[{"name":"pork","amount":130,"unit":"g"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"lettuce","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["1 tsp mustard","splash of vinegar","salt","black pepper"]'::jsonb, '["Cut the pork into thin strips, season and fry in half the olive oil over high heat for 4 to 5 minutes","Slice the apple and cucumber thinly and tear the lettuce","Whisk the remaining olive oil with the mustard, vinegar, salt and pepper","Toss the salad in the dressing, top with the pork and serve with the bread"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","pork","apple","lettuce","cucumber","olive oil","bread","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Салата със свинско и ябълка","description":"Запържени ивици свинско върху маруля с ябълка, краставица и дресинг с горчица","instructions":["Нарежете свинското на тънки ивици, овкусете ги и ги запържете в половината зехтин на силен огън за 4–5 минути","Нарежете ябълката и краставицата на тънки резени и накъсайте марулята","Разбийте останалия зехтин с горчицата, оцета, сол и пипер","Разбъркайте салатата с дресинга, сложете свинското отгоре и поднесете с хляба"],"seasonings":["1 ч.л. горчица","малко оцет","сол","черен пипер"]},"nl":{"name":"Salade met varkensvlees en appel","description":"Gebakken reepjes varkensvlees op sla met appel, komkommer en een mosterddressing","instructions":["Snijd het varkensvlees in dunne reepjes, kruid ze en bak ze 4 tot 5 minuten in de helft van de olijfolie op hoog vuur","Snijd de appel en de komkommer in dunne plakjes en scheur de sla","Klop de rest van de olijfolie met de mosterd, de azijn, zout en peper","Schep de salade door de dressing, leg het vlees erop en serveer met het brood"],"seasonings":["1 tl mosterd","scheutje azijn","zout","zwarte peper"]}}'::jsonb, 229),
  ('l-chicken-pesto-panini', 'Chicken Pesto Panini', 'Pressed sandwich with chicken, mozzarella, tomato and pesto', 'lunch', 'chicken', '🥪', 20, 'quick', 745, 62, 51, 32, 8, 7, 1090, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"bread","amount":105,"unit":"g","label":"3 slices"},{"name":"mozzarella","amount":60,"unit":"g"},{"name":"pesto","amount":25,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Season the chicken and fry it in a non-stick pan over medium heat for 5 to 6 minutes per side, then slice","Spread the pesto on the bread and layer on the chicken, sliced mozzarella and sliced tomato to make a double-decker sandwich","Toast it in the dry pan over medium heat, pressing down with a spatula, for 2 to 3 minutes per side until the cheese melts"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","hearty","chicken","bread","mozzarella","pesto","tomato","stovetop","lunch"]'::jsonb, '["halal"]'::jsonb, '{"bg":{"name":"Панини с пилешко и песто","description":"Притиснат сандвич с пилешко, моцарела, домат и песто","instructions":["Овкусете пилешкото и го изпържете в незалепващ тиган на среден огън по 5–6 минути от всяка страна, след което го нарежете","Намажете пестото върху хляба и наредете пилешкото, нарязаната моцарела и нарязания домат, така че да се получи сандвич на два етажа","Запечете го в сухия тиган на среден огън по 2–3 минути от всяка страна, като го притискате с шпатула, докато моцарелата се разтопи"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Panini met kip en pesto","description":"Geperste sandwich met kip, mozzarella, tomaat en pesto","instructions":["Kruid de kip en bak hem in een koekenpan met antiaanbaklaag op middelhoog vuur 5 tot 6 minuten per kant; snijd hem dan in plakken","Smeer de pesto op het brood en beleg met de kip, de plakjes mozzarella en de plakjes tomaat tot een sandwich van twee lagen","Bak hem in de droge pan op middelhoog vuur 2 tot 3 minuten per kant en druk hem aan met een spatel, tot de kaas smelt"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 230),
  ('l-beef-bean-burrito', 'Beef and Bean Lunch Burritos', 'Two burritos with spiced beef mince, kidney beans and cheese', 'lunch', 'beef mince', '🌯', 20, 'quick', 825, 46, 75, 37, 8, 9, 1281, '[{"name":"beef mince","amount":140,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt"]'::jsonb, '["Brown the beef mince in a dry pan over high heat for 6 minutes","Add the cumin, paprika, salt, drained kidney beans and a splash of water and cook for 2 minutes","Warm the tortillas in a dry pan","Fill them with the beef and beans, grated cheese and diced tomato, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","hearty","beef mince","tortilla","kidney beans","cheese","tomato","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Бурито с телешка кайма и боб за обяд","description":"Две бурито с телешка кайма с подправки, червен боб и кашкавал","instructions":["Запържете телешката кайма в сух тиган на силен огън за 6 минути","Добавете кимиона, червения пипер, сол, отцедения червен боб и малко вода и гответе 2 минути","Затоплете тортилите в сух тиган","Напълнете ги с каймата и боба, настъргания кашкавал и нарязания на кубчета домат, подгънете краищата и навийте"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","сол"]},"nl":{"name":"Lunchburrito''s met rundergehakt en bonen","description":"Twee burrito''s met gekruid rundergehakt, kidneybonen en kaas","instructions":["Bak het rundergehakt 6 minuten bruin in een droge pan op hoog vuur","Voeg de komijn, het paprikapoeder, zout, de uitgelekte kidneybonen en een scheutje water toe en bak 2 minuten","Verwarm de tortilla''s in een droge pan","Vul ze met het gehakt en de bonen, de geraspte kaas en de tomatenblokjes, vouw de zijkanten naar binnen en rol op"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","zout"]}}'::jsonb, 231),
  ('l-salmon-avocado-rice-bowl', 'Salmon and Avocado Rice Bowl', 'Pan-fried salmon over rice with avocado, cucumber and soy', 'lunch', 'salmon', '🍣', 20, 'quick', 825, 38, 79, 40, 11, 2, 647, '[{"name":"salmon","amount":140,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"g"}]'::jsonb, '["squeeze of lime juice","sesame seeds if you have them"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Fry the salmon in a non-stick pan over medium heat for 3 to 4 minutes per side and break into large flakes","Slice the avocado and cucumber","Top the rice with the salmon, avocado and cucumber and dress with the soy sauce and lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","fresh","quick","hearty","salmon","rice","avocado","cucumber","soy sauce","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа ориз със сьомга и авокадо","description":"Сьомга на тиган върху ориз с авокадо, краставица и соев сос","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Изпържете сьомгата в незалепващ тиган на среден огън по 3–4 минути от всяка страна и я разделете на едри парчета","Нарежете авокадото и краставицата на резени","Сложете върху ориза сьомгата, авокадото и краставицата и овкусете със соевия сос и сока от лайм"],"seasonings":["няколко капки сок от лайм","сусам, ако имате"]},"nl":{"name":"Rijstkom met zalm en avocado","description":"Gebakken zalm op rijst met avocado, komkommer en soja","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Bak de zalm 3 tot 4 minuten per kant in een koekenpan met antiaanbaklaag op middelhoog vuur en trek hem in grote stukken","Snijd de avocado en de komkommer in plakjes","Leg de zalm, de avocado en de komkommer op de rijst en maak aan met de sojasaus en het limoensap"],"seasonings":["kneepje limoensap","sesamzaad als je het hebt"]}}'::jsonb, 232),
  ('l-peanut-chicken-noodles', 'Peanut Chicken Noodles', 'Warm noodles with chicken and carrot in a peanut soy sauce', 'lunch', 'chicken', '🥜', 20, 'quick', 752, 54, 76, 26, 6, 7, 1058, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"noodles","amount":90,"unit":"g"},{"name":"peanut butter","amount":25,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["3 tbsp hot water","squeeze of lime juice"]'::jsonb, '["Cook the noodles according to the packet and drain","Slice the chicken and stir-fry it in the oil over high heat for 5 minutes with the carrots cut into thin strips","Whisk the peanut butter with the soy sauce, hot water and lime juice","Toss the noodles and sauce through the chicken and heat for 1 minute"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","hearty","chicken","noodles","peanut butter","carrots","soy sauce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","halal","kosher"]'::jsonb, '{"bg":{"name":"Нудли с пилешко и фъстъчен сос","description":"Топли нудли с пилешко и морков в сос от фъстъчено масло и соев сос","instructions":["Сварете нудлите според указанията на опаковката и ги отцедете","Нарежете пилешкото на ивици и го запържете в олиото на силен огън за 5 минути заедно с нарязаните на тънки лентички моркови, като бъркате","Разбийте фъстъченото масло със соевия сос, горещата вода и сока от лайм","Добавете нудлите и соса към пилешкото, разбъркайте и затоплете 1 минута"],"seasonings":["3 с.л. гореща вода","няколко капки сок от лайм"]},"nl":{"name":"Noedels met kip en pinda","description":"Warme noedels met kip en wortel in een pinda-sojasaus","instructions":["Kook de noedels volgens de verpakking en giet af","Snijd de kip in reepjes en roerbak hem 5 minuten in de olie op hoog vuur met de wortels in dunne reepjes","Klop de pindakaas met de sojasaus, het hete water en het limoensap","Schep de noedels en de saus door de kip en verwarm 1 minuut"],"sea