  ('l-beef-egg-fried-rice', 'Beef and Egg Fried Rice', 'Fried rice with beef strips, scrambled egg and peas', 'lunch', 'beef', '🍚', 20, 'quick', 791, 53, 80, 27, 4, 3, 1111, '[{"name":"beef","amount":130,"unit":"g"},{"name":"rice","amount":90,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"peas","amount":50,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["black pepper","1 tsp grated ginger"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it steam dry","Slice the beef thinly and sear it in the oil over very high heat for 2 minutes with the ginger","Push it aside, scramble the eggs in the gap, then add the peas","Add the rice and soy sauce and stir-fry for 2 minutes"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","hearty","beef","rice","eggs","peas","soy sauce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пържен ориз с телешко и яйца","description":"Пържен ориз с ивици телешко, бъркани яйца и грах","instructions":["Сварете ориза в подсолена вода за 10–12 минути, отцедете го и го оставете да изсъхне на парата","Нарежете телешкото на тънки ивици и го запечатайте в олиото на много силен огън за 2 минути с джинджифила","Избутайте го настрани, разбъркайте яйцата в празното място и добавете граха","Добавете ориза и соевия сос и пържете 2 минути, като бъркате"],"seasonings":["черен пипер","1 ч.л. настърган джинджифил"]},"nl":{"name":"Gebakken rijst met rundvlees en ei","description":"Gebakken rijst met reepjes rundvlees, roerei en doperwten","instructions":["Kook de rijst 10 tot 12 minuten in water met zout, giet af en laat hem droog stomen","Snijd het rundvlees in dunne reepjes en schroei het 2 minuten in de olie op zeer hoog vuur met de gember","Schuif het opzij, roer de eieren in de vrije ruimte tot roerei en voeg dan de doperwten toe","Voeg de rijst en de sojasaus toe en roerbak 2 minuten"],"