  ('l-tofu-peanut-rice-bowl', 'Tofu Peanut Rice Bowl', 'Golden tofu over rice with carrot, cucumber and a peanut soy sauce', 'lunch', 'tofu', '🥜', 20, 'quick', 832, 48, 88, 36, 9, 7, 841, '[{"name":"tofu","amount":200,"unit":"g"},{"name":"rice","amount":85,"unit":"g"},{"name":"peanut butter","amount":25,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"},{"name":"soy sauce","amount":12,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["3 tbsp hot water","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Cut the tofu into cubes and fry in the oil over medium-high heat for 6 minutes until golden","Whisk the peanut butter with the soy sauce, hot water and lime juice","Serve the tofu over the rice with the grated carrots and sliced cucumber and pour over the sauce"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","hearty","tofu","rice","peanut butter","carrots","cucumber","soy sauce","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа ориз с тофу и фъстъчен сос","description":"Златисто тофу върху ориз с морков, краставица и сос от фъстъчено масло и соев сос","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Нарежете тофуто на кубчета и го запържете в олиото на умерено силен огън за 6 минути до златисто","Разбийте фъстъченото масло със соевия сос, горещата вода и сока от лайм","Поднесете тофуто върху ориза с настърганите моркови и нарязаната краставица и полейте със соса"],"seasonings":["3 с.л. гореща вода","няколко капки сок от лайм"]},"nl":{"name":"Rijstkom met tofu en pinda","description":"Goudbruine tofu op rijst met wortel, komkommer en een pinda-sojasaus","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Snijd de tofu in blokjes en bak ze 6 minuten in de olie op middelhoog tot hoog vuur goudbruin","Klop de pindakaas met de sojasaus, he